from math import comb

def R(n):
    if n < 4:
        return 0
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)
    if f_kn == 0:
        return 0 # Should only happen for n < 3
    return (g_kn**3) / (f_kn**4)

# Check values around n=10 and higher
n_values = [7, 10, 12, 15, 20]
print("n\tR_n")
for n in n_values:
    r = R(n)
    print(f"{n}\t{r}")
